def get_status_code(self, srvHost, reqPath='/'):
    try:
        with socket.create_connection((srvHost, 80)) as conn:
            conn.sendall(f'HEAD {reqPath} HTTP/1.0\r\nHost: {srvHost}\r\n\r\n'.encode('utf-8'))
            response = conn.recv(1024)
            status_code = response.split()[1]
            return int(status_code)
    except:
        return None
